cat >> test/documents.test.mjs <<'EOF'

// Scenario: Given document 42 of tenant b, When a tenant a caller reads it,
// Then NotFoundError with the same message as for a missing document.
test("another tenant's document is indistinguishable from a missing one", () => {
  const documents = [{ id: 42, tenantId: "b", title: "Secret" }];
  const message = (id, caller) => {
    try {
      readDocument(documents, caller, id);
    } catch (error) {
      assert.ok(error instanceof NotFoundError);
      return error.message;
    }
    assert.fail("expected NotFoundError");
  };
  assert.equal(message(42, { tenantId: "a" }), "document 42 not found");
  assert.equal(message(42, { tenantId: "a" }), message(42, { tenantId: "a" }));
});

// Scenario: Given a caller without a tenant, When reading any document, Then NotFoundError.
for (const caller of [{}, { tenantId: undefined }, { tenantId: null }, { tenantId: "" }, null, undefined]) {
  test(`caller ${JSON.stringify(caller)} without a tenant reads nothing`, () => {
    const documents = [
      { id: 1, tenantId: "a" },
      { id: 2 },
      { id: 3, tenantId: undefined },
      { id: 4, tenantId: null },
    ];
    for (const { id } of documents) {
      assert.throws(() => readDocument(documents, caller, id), NotFoundError);
    }
  });
}
EOF
sed -i 's/import { readDocument }/import { NotFoundError, readDocument }/' test/documents.test.mjs
npm test 2>&1 | grep -E "^# (pass|fail)"
cat > src/documents.mjs <<'EOF'
export class NotFoundError extends Error {}

// Returns the document with `id` for an authenticated caller ({ tenantId }).
// Documents of other tenants, or any document for a caller without a tenant,
// are reported exactly like missing ones.
export function readDocument(documents, caller, id) {
  const tenantId = caller?.tenantId;
  const document =
    typeof tenantId === "string" && tenantId !== ""
      ? documents.find((candidate) => candidate.id === id && candidate.tenantId === tenantId)
      : undefined;
  if (!document) throw new NotFoundError(`document ${id} not found`);
  return document;
}
EOF
npm test 2>&1 | grep -E "^# (pass|fail)"

cat >> test/documents.test.mjs <<'EOF'

// Given document 42 of tenant b, when a tenant a caller reads it,
// then it fails exactly like a missing document.
test("another tenant's document is indistinguishable from a missing one", () => {
  const documents = [{ id: 42, tenantId: "b", title: "Secret" }];
  const caller = { tenantId: "a" };
  const foreign = assert.throws(() => readDocument(documents, caller, 42), NotFoundError);
  assert.throws(() => readDocument(documents, caller, 42), { message: "document 42 not found" });
  assert.throws(() => readDocument([], caller, 42), { message: "document 42 not found" });
});

// Given a caller without a tenant, when reading any document, then NotFoundError.
test("a caller without a tenant reads nothing", () => {
  const documents = [{ id: 1, tenantId: "a" }, { id: 2 }, { id: 3, tenantId: null }];
  for (const caller of [{}, { tenantId: undefined }, { tenantId: null }, { tenantId: "" }, null, undefined]) {
    for (const { id } of documents) {
      assert.throws(() => readDocument(documents, caller, id), NotFoundError);
    }
  }
});
EOF
npm test 2>&1 | grep -E "^# (pass|fail)"
